/**
 * Flow graphic — EDITOR → MCP → AGENT, with a diff "packet" travelling the
 * connectors (global .m-travel). Node outlines/glyphs draw themselves in. Theme
 * vars from .nco-motion. Generated by a sub-agent, integrated + corrected
 * (removed a local <style> that clobbered global classes; descriptive captions).
 */

export default function McpFlow() {
  const canvasW = 760;
  const canvasH = 240;
  const nodeW = 150;
  const nodeH = 90;
  const nodeY = (canvasH - nodeH) / 2;
  const cy = nodeY + nodeH / 2;
  const spacing = canvasW / 4;

  const nodes = [
    { cx: spacing, label: 'EDITOR', caption: 'chrome extension' },
    { cx: 2 * spacing, label: 'MCP', caption: 'local server' },
    { cx: 3 * spacing, label: 'AGENT', caption: 'any LLM' },
  ];
  const x = (cx: number) => cx - nodeW / 2;

  const conn1StartX = x(nodes[0].cx) + nodeW;
  const conn1EndX = x(nodes[1].cx);
  const conn2StartX = x(nodes[1].cx) + nodeW;
  const conn2EndX = x(nodes[2].cx);

  return (
    <svg
      viewBox={`0 0 ${canvasW} ${canvasH}`}
      width="100%"
      height="100%"
      role="img"
      aria-label="Flow: the editor sends a structured diff through MCP to your AI coding agent"
      preserveAspectRatio="xMidYMid meet"
      style={{ display: 'block' }}
    >
      {/* static base connectors */}
      <line x1={conn1StartX} y1={cy} x2={conn1EndX} y2={cy} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" aria-hidden="true" />
      <line x1={conn2StartX} y1={cy} x2={conn2EndX} y2={cy} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" aria-hidden="true" />

      {/* travelling diff packet across both connectors */}
      <path d={`M ${conn1StartX} ${cy} L ${conn2EndX} ${cy}`} pathLength={1} className="m-travel" stroke="var(--m-accent)" strokeWidth={2.5} strokeLinecap="round" fill="none" aria-hidden="true" />

      {/* arrow heads */}
      <polyline points={`${conn1EndX - 8},${cy - 5} ${conn1EndX},${cy} ${conn1EndX - 8},${cy + 5}`} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.25s' }} aria-hidden="true" />
      <polyline points={`${conn2EndX - 8},${cy - 5} ${conn2EndX},${cy} ${conn2EndX - 8},${cy + 5}`} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.58s' }} aria-hidden="true" />

      {/* connector micro-labels */}
      <text x={(conn1StartX + conn1EndX) / 2} y={cy - 8} textAnchor="middle" fontSize={9} fontFamily="var(--m-mono)" fill="var(--m-accent)" aria-hidden="true">diff</text>
      <text x={(conn2StartX + conn2EndX) / 2} y={cy - 8} textAnchor="middle" fontSize={9} fontFamily="var(--m-mono)" fill="var(--m-accent)" aria-hidden="true">tool call</text>

      {nodes.map((n, i) => (
        <g key={n.label}>
          <rect x={x(n.cx)} y={nodeY} width={nodeW} height={nodeH} rx={6} fill="var(--m-bg-2)" stroke="var(--m-line-2)" strokeWidth={1.5} pathLength={1} className="m-draw" style={{ animationDelay: `${i * 0.3}s` }} aria-hidden="true" />

          {/* glyph */}
          {i === 0 && (
            <g aria-hidden="true">
              <rect x={n.cx - 28} y={cy - 24} width={56} height={32} rx={3} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.06s' }} />
              <line x1={n.cx - 28} y1={cy - 14} x2={n.cx + 28} y2={cy - 14} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.1s' }} />
              <line x1={n.cx - 20} y1={cy - 2} x2={n.cx + 14} y2={cy - 2} stroke="var(--m-line-2)" strokeWidth={1.2} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.16s' }} />
              <line x1={n.cx - 20} y1={cy + 4} x2={n.cx + 4} y2={cy + 4} stroke="var(--m-line-2)" strokeWidth={1.2} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.2s' }} />
            </g>
          )}
          {i === 1 && (
            <g aria-hidden="true">
              <circle cx={n.cx} cy={cy - 6} r={7} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} pathLength={1} className="m-draw" style={{ animationDelay: '0.35s' }} />
              <line x1={n.cx} y1={cy - 13} x2={n.cx} y2={cy - 20} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.38s' }} />
              <line x1={n.cx} y1={cy + 1} x2={n.cx} y2={cy + 8} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.41s' }} />
              <line x1={n.cx - 7} y1={cy - 6} x2={n.cx - 14} y2={cy - 6} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.44s' }} />
              <line x1={n.cx + 7} y1={cy - 6} x2={n.cx + 14} y2={cy - 6} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.47s' }} />
            </g>
          )}
          {i === 2 && (
            <g aria-hidden="true">
              {[0, 60, 120].map((deg, k) => {
                const rad = (deg * Math.PI) / 180;
                const dx = Math.cos(rad) * 15;
                const dy = Math.sin(rad) * 15;
                return (
                  <line key={deg} x1={n.cx - dx} y1={cy - 6 - dy} x2={n.cx + dx} y2={cy - 6 + dy} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: `${0.65 + k * 0.05}s` }} />
                );
              })}
            </g>
          )}

          <text x={n.cx} y={nodeY + nodeH - 12} textAnchor="middle" fontSize={12} fontFamily="var(--m-mono)" fill="var(--m-fg)">{n.label}</text>
          <text x={n.cx} y={nodeY + nodeH + 18} textAnchor="middle" fontSize={10} fontFamily="var(--m-mono)" fill="var(--m-fg-dim)">{n.caption}</text>
        </g>
      ))}
    </svg>
  );
}
